#!/usr/bin/env python3
"""Validate and unpack experiment text packages without trusting file paths."""
import argparse
import base64
import hashlib
import json
from pathlib import Path,PurePosixPath

BASE=Path(__file__).resolve().parent

def unpack(path,case,supplement=False):
    package=json.loads(path.read_text())
    files=package['files']; hashes=package['sha256']
    if set(files)!=set(hashes):raise ValueError('File/hash key sets differ')
    validated=[]
    for name,content in files.items():
        rel=PurePosixPath(name)
        if rel.is_absolute() or '..' in rel.parts or '\\' in name:raise ValueError('Unsafe package path')
        if not name.startswith(f'runs/{case}/remote/'):raise ValueError('Unexpected case prefix: '+name)
        data=content.encode('utf-8')
        if hashlib.sha256(data).hexdigest()!=hashes[name]:raise ValueError('Digest mismatch: '+name)
        target=BASE/name
        if target.exists() and target.read_bytes()!=data:raise ValueError('Refusing evidence overwrite: '+name)
        validated.append((target,data))
    for target,data in validated:
        target.parent.mkdir(parents=True,exist_ok=True)
        if not target.exists():target.write_bytes(data)
    bundles=list((BASE/'runs'/case/'remote').rglob('return-bundle.json'))
    if len(bundles)==1:
        bundle=json.loads(bundles[0].read_text());data=base64.b64decode(bundle['data'],validate=True)
        if hashlib.sha256(data).hexdigest()!=bundle['sha256']:raise ValueError('Return archive checksum mismatch')
        target=BASE/'runs'/case/'evidence/return.zip'
        if target.exists() and target.read_bytes()!=data:raise ValueError('Refusing return archive replacement')
        if not target.exists():target.write_bytes(data)
    report={'case':case,'artifact_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
            'file_count':len(files),'all_file_hashes_valid':True,'return_bundle_count':len(bundles),
            'notes':package.get('notes')}
    target=BASE/'runs'/case/'evidence'/('supplement-package-verification.json' if supplement else 'package-verification.json')
    with target.open('x') as f:json.dump(report,f,indent=2);f.write('\n')
    print(json.dumps(report,indent=2))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('package',type=Path);p.add_argument('case');p.add_argument('--supplement',action='store_true');a=p.parse_args();unpack(a.package,a.case,a.supplement)

