#!/usr/bin/env python3
"""Prepare synthetic-only local evidence and a readable report on the study branch."""
from datetime import datetime,timezone
import hashlib
import json
from pathlib import Path
import re
import shutil

B=Path(__file__).resolve().parent
summary=json.loads((B/'RESULTS.json').read_text())
if not summary['all_cases_verified']:
    raise RuntimeError('Do not publish an all-complete report before every case is verified')
files={}
for folder in ['protocol','cases','evidence']:
    for p in sorted((B/folder).glob('*')):
        if p.is_file() and p.suffix in ['.py','.md','.json','.log'] and not p.name.endswith('-return-package.json'):
            files[str(p.relative_to(B))]=p.read_text()
for p in sorted(B.glob('*.py')):
    files[p.name]=p.read_text()
for name in ['RESULTS.md','RESULTS.json','PAPER-NOTES.md']:
    if (B/name).exists():files[name]=(B/name).read_text()
for row in summary['cases']:
    case=row['case'];run=B/'runs'/case
    for p in sorted((run/'evidence').rglob('*')):
        if p.is_file() and p.suffix in ['.json','.jsonl','.log','.md','.txt']:
            files[str(p.relative_to(B))]=p.read_text()
    roots=['source'] if row['arm']=='control' else ['source','returned']
    for root in roots:
        for rel in ['self.json','memory/long_term.json','task_queue.json','artifacts/task_events.jsonl','daemon_epoch.json','migration_source.json','migration_target.json','migration-report.json']:
            p=run/root/'.enoch'/rel
            if p.is_file():files[f'runs/{case}/native-{root}/{rel}']=p.read_text()
        for p in sorted((run/root/'.enoch/artifacts/migrations').glob('*/migration-report.json')):
            files[f'runs/{case}/native-{root}/'+str(p.relative_to(run/root/'.enoch'))]=p.read_text()
package={'study_id':B.name,'published_at':datetime.now(timezone.utc).isoformat(),
         'notes':'Synthetic experiment evidence only. Muse return packages remain at their original commits. Default zero Muse usage means unavailable.',
         'files':files,'sha256':{k:hashlib.sha256(v.encode()).hexdigest() for k,v in files.items()}}
data=json.dumps(package,indent=2)+'\n'
if re.search(r'(gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|sk-[A-Za-z0-9]{20,}|-----BEGIN (RSA |OPENSSH )?PRIVATE KEY)',data):
    raise RuntimeError('Credential-shaped data requires inspection before publication')
out=B/'exchange/experiments/ripa-study-20260919'
groups={key:{} for key in ['common','qualification','repeats','controls','fault']}
for name,value in files.items():
    case=name.split('/')[1] if name.startswith('runs/') else None
    group='qualification' if case=='Q' else 'fault' if case=='F' else 'repeats' if case and case.startswith('R') else 'controls' if case and case.startswith('C') else 'common'
    groups[group][name]=value
parts=[]
for group,entries in groups.items():
    part={**package,'files':entries,'sha256':{k:package['sha256'][k] for k in entries}}
    text=json.dumps(part,indent=2)+'\n'
    name=f'local-{group}-package.json'
    (out/name).write_text(text)
    parts.append({'path':name,'sha256':hashlib.sha256(text.encode()).hexdigest(),'file_count':len(entries),'bytes':len(text)})
(out/'local-verification-package.json').write_text(json.dumps({'study_id':B.name,'parts':parts,'total_files':len(files),'all_cases_verified':True},indent=2)+'\n')
